// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 当前审计权限私有CSV导出
	// (POST /v1/audit-exports)
	CreateAuditExport(ctx context.Context, request CreateAuditExportRequestObject) (CreateAuditExportResponseObject, error)
	// 当前权限同主体私有CSV下载
	// (GET /v1/audit-exports/{exportId})
	DownloadAuditExport(ctx context.Context, request DownloadAuditExportRequestObject) (DownloadAuditExportResponseObject, error)
	// 审计分页
	// (GET /v1/audits)
	QueryAudits(ctx context.Context, request QueryAuditsRequestObject) (QueryAuditsResponseObject, error)
	// 追加安全审计
	// (POST /v1/audits)
	AppendAudit(ctx context.Context, request AppendAuditRequestObject) (AppendAuditResponseObject, error)
	// 读取单条审计
	// (GET /v1/audits/{auditId})
	ReadAudit(ctx context.Context, request ReadAuditRequestObject) (ReadAuditResponseObject, error)
	// 匿名HTTP接收
	// (POST /v1/beacons)
	IngestBeacon(ctx context.Context, request IngestBeaconRequestObject) (IngestBeaconResponseObject, error)
	// AI Markdown访问独立计数
	// (POST /v1/crawler-access)
	RecordCrawlerAccess(ctx context.Context, request RecordCrawlerAccessRequestObject) (RecordCrawlerAccessResponseObject, error)
	// 可信portal匿名访问转交
	// (POST /v1/internal/beacons)
	IngestTrustedBeacon(ctx context.Context, request IngestTrustedBeaconRequestObject) (IngestTrustedBeaconResponseObject, error)
	// 读取原统计聚合任务恢复证明
	// (POST /v1/jobs/{jobId}/recovery)
	ReadJobRecovery(ctx context.Context, request ReadJobRecoveryRequestObject) (ReadJobRecoveryResponseObject, error)
	// 热门文档与答不出问题联动
	// (GET /v1/statistics/content-gaps)
	QueryContentGaps(ctx context.Context, request QueryContentGapsRequestObject) (QueryContentGapsResponseObject, error)
	// 当前权限同主体私有CSV下载
	// (GET /v1/statistics/exports/{exportId})
	DownloadStatisticsExport(ctx context.Context, request DownloadStatisticsExportRequestObject) (DownloadStatisticsExportResponseObject, error)
	// 访问汇总查询
	// (GET /v1/statistics/pages)
	QueryPageStatistics(ctx context.Context, request QueryPageStatisticsRequestObject) (QueryPageStatisticsResponseObject, error)
	// 费用汇总查询
	// (GET /v1/statistics/usage)
	QueryUsageStatistics(ctx context.Context, request QueryUsageStatisticsRequestObject) (QueryUsageStatisticsResponseObject, error)
	// 按唯一访客查看活动和设备信息
	// (GET /v1/statistics/visitors)
	ListVisitors(ctx context.Context, request ListVisitorsRequestObject) (ListVisitorsResponseObject, error)
	// 受权限保护统计导出
	// (POST /v1/statistics:export)
	CreateExport(ctx context.Context, request CreateExportRequestObject) (CreateExportResponseObject, error)
	// 对账修复派生统计
	// (POST /v1/usage:reconcile)
	ReconcileUsage(ctx context.Context, request ReconcileUsageRequestObject) (ReconcileUsageResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

